    const seconds = retry ? (/^\d+(\.\d+)?$/.test(retry) ? Number(retry) : (Date.parse(retry) - Date.now()) / 1000) : NaN;
    throw new ProviderError(response.status, Number.isFinite(seconds) ? Math.max(1, Math.ceil(seconds)) : null);
  }
